"""Recurring staff-task templates (series). Occurrences are generated by
routes/task_recurrence.py (escalation tick + the admin route below); this file
manages the series definitions. Creating and deleting a series is receipted.
"""
from fastapi import APIRouter, HTTPException, Depends

from models import StaffTaskTemplate, StaffTaskTemplateCreate
from deps import db, get_current_user
from routes.tasks import _iso
from routes.actor_context import actor_from_user
from routes.receipts import create_receipt
from routes import task_recurrence

router = APIRouter(prefix="/tasks", tags=["task-templates"])
ADMIN = ("owner", "admin")


def _require_admin(user):
    if user.get("role") not in ADMIN:
        raise HTTPException(status_code=403, detail="Admin required")


async def _receipt(action: str, tpl: dict, user: dict, before=None, after=None):
    await create_receipt(
        action_type=action, related_object_type="task_template", related_object_id=tpl["template_id"],
        source="staff", resident_id=tpl.get("resident_id"), room=tpl.get("room"), status="completed",
        result=tpl.get("title"),
        provenance={**actor_from_user(user).receipt_fields(), "authority": f"admin_override:{user['role']}",
                    "before_state": before, "after_state": after, "result_label": "verified"})


def _schedule_fields(tpl: dict) -> dict:
    return {k: tpl.get(k) for k in ("recur", "weekday", "time_label", "department", "resident_id", "room",
                                    "provider_name", "discipline", "location", "active")}


@router.get("/templates/all")
async def list_templates(user=Depends(get_current_user)):
    items = await db.task_templates.find({}, {"_id": 0}).sort("title", 1).to_list(500)
    for t in items:
        _iso(t)
    return items


@router.post("/templates")
async def create_template(data: StaffTaskTemplateCreate, user=Depends(get_current_user)):
    _require_admin(user)
    if data.recur == "weekly" and data.weekday is None:
        raise HTTPException(status_code=422, detail="A weekly series needs a day of the week")
    if data.department and not await db.departments.find_one({"slug": data.department}, {"_id": 1}):
        raise HTTPException(status_code=422, detail="Unknown department")
    fields = data.model_dump()
    for k in ("provider_name", "discipline", "location", "time_label"):
        fields[k] = (fields.get(k) or "").strip() or None
    if fields.get("resident_id") and not fields.get("room"):
        r = await db.residents.find_one({"resident_id": fields["resident_id"]}, {"_id": 0, "room": 1})
        if not r:
            raise HTTPException(status_code=422, detail="Unknown resident")
        fields["room"] = r.get("room")
    doc = StaffTaskTemplate(**fields).model_dump()
    doc["created_at"] = doc["created_at"].isoformat()
    await db.task_templates.insert_one(doc)
    doc.pop("_id", None)
    await _receipt("task_template_created", doc, user, after=_schedule_fields(doc))
    return doc


@router.delete("/templates/{template_id}")
async def delete_template(template_id: str, user=Depends(get_current_user)):
    """Ends the series. Occurrences already created stay as they are."""
    _require_admin(user)
    tpl = await db.task_templates.find_one({"template_id": template_id}, {"_id": 0})
    if not tpl:
        raise HTTPException(status_code=404, detail="Template not found")
    await db.task_templates.delete_one({"template_id": template_id})
    await _receipt("task_template_deleted", tpl, user, before=_schedule_fields(tpl))
    return {"ok": True}


@router.post("/spawn-today")
async def spawn_today(user=Depends(get_current_user)):
    """Generate due occurrences now (the tick does this on its own; idempotent)."""
    _require_admin(user)
    out = await task_recurrence.generate()
    return {"ok": True, **out, "created": out["occurrences_created"]}   # "created": older callers
